mapper.select:
select
from task_info t where is_valid =1 and is_audit =1
AND id = #{id,jdbcType=BIGINT}

select r.id AS id, r.task_name AS taskName, r.task_org AS taskOrg, r.task_desc AS taskDesc, r.task_time AS taskTime, r.is_valid AS isValid, r.is_audit AS isAudit, s.name AS creatorName, r.create_time AS createTime, u.name AS editorName, r.edit_time AS editTime, e.name AS auditorName, r.audit_time AS auditTime from task_info r left join sys_user s on r.creator_id=s.id left join sys_user u on r.editor_id=u.id left join sys_user e on r.auditor_id=e.id
AND ${page.where}
AND r.IS_VALID != -1
AND r.task_name like CONCAT('%',#{taskName}, '%')
AND r.is_audit=${isAudit}
AND r.task_time >= #{beginDate}
AND r.task_time <= #{endDate}
AND r.edit_time >= #{dobeginDate}
AND r.edit_time <= #{doendDate}
${sqlMap.dsf}
ORDER BY ${page.orderBy}
ORDER BY r.create_time desc
